"""Manage workspace CRM custom field definitions through the existing API."""
from fastapi import APIRouter, Response
from fastapi.responses import HTMLResponse
from funnel_crm.web.crm_operations_workspace import _HEADERS

router = APIRouter(tags=["CRM custom field workspace"], include_in_schema=False)
_PAGE = """<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>فیلدهای سفارشی | فانل CRM</title><style>[hidden]{display:none!important}
:root{font-family:Tahoma,Arial,sans-serif;color:#172c42;background:#f4f7fb;font-synthesis:none}*{box-sizing:border-box}body{margin:0}.app{min-height:100vh;display:grid;grid-template-columns:230px minmax(0,1fr)}aside{background:#fff;border-left:1px solid #e3e9f0;padding:20px 14px;position:sticky;top:0;height:100vh}.brand{font-size:19px;font-weight:800;padding:0 10px 24px}.brand b{color:#158b91}nav{display:grid;gap:5px}.nav{display:block;padding:11px;border-radius:9px;color:#54677a;text-decoration:none;font-size:12px}.nav:hover,.nav.active{background:#eaf4f7;color:#125779}.main{min-width:0;padding:24px clamp(16px,3vw,42px) 48px}.top{display:flex;align-items:center;gap:12px;margin-bottom:24px}.top select{min-width:190px}h1{font-size:25px;margin:0 0 8px}.sub{color:#718092;font-size:13px;line-height:1.8;margin:0}.head{display:flex;justify-content:space-between;align-items:flex-end;gap:18px;margin-bottom:20px}.filters{display:flex;gap:8px;align-items:end;flex-wrap:wrap}.filters label,.field{display:grid;gap:6px;font-size:11px;color:#778697}input,select,textarea{font:inherit;color:#33465c;border:1px solid #dfe6ed;background:#fff;border-radius:9px;padding:10px;min-width:140px}button{font:inherit;cursor:pointer}.primary{border:0;background:#126b91;color:white;border-radius:9px;padding:11px 16px;font-weight:700}.secondary{border:1px solid #d8e2ea;background:white;color:#31536c;border-radius:8px;padding:8px 11px}.kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:14px 0}.card{background:#fff;border:1px solid #e5eaf0;border-radius:12px;padding:16px;box-shadow:0 4px 14px #1c334408}.label{color:#657487;font-size:12px}.value{font-size:23px;font-weight:800;margin:11px 0 4px}.meta{color:#8290a0;font-size:10px}.layout{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(280px,.8fr);gap:14px}.section-title{display:flex;justify-content:space-between;align-items:center;margin:0 0 12px;font-size:15px}.queue{display:grid;gap:9px}.task{border:1px solid #e8edf2;border-radius:10px;padding:13px;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:center}.task strong{font-size:13px}.task p{margin:6px 0 0;color:#728093;font-size:11px;line-height:1.7}.chips{display:flex;gap:5px;flex-wrap:wrap;margin-top:7px}.chip{font-size:10px;background:#eff4f7;color:#526b7e;border-radius:99px;padding:4px 8px}.chip.late{background:#fff0eb;color:#a34e36}.actions{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end}.form{display:grid;gap:12px}.form textarea{min-height:75px;resize:vertical}.form-row{display:grid;grid-template-columns:1fr 1fr;gap:8px}.notice{color:#718092;font-size:11px;line-height:1.8;margin-top:12px}.empty{border:1px dashed #d4dde6;border-radius:9px;padding:20px;color:#7b8998;font-size:12px;text-align:center;line-height:1.8}#status{min-height:20px;color:#718092;font-size:12px;margin:0 0 8px}#status.error{color:#a74137}
@media(max-width:900px){.layout{grid-template-columns:1fr}}@media(max-width:760px){.app{display:block}aside{position:relative;height:auto;border:0;border-bottom:1px solid #e3e9f0;padding:12px}.brand{padding-bottom:9px}nav{display:flex;overflow:auto}.nav{white-space:nowrap}.head{display:block}.filters{margin-top:14px}.kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:480px){.main{padding:15px 12px 32px}.top{align-items:stretch;flex-direction:column}.top select{width:100%}.filters{display:grid;grid-template-columns:1fr 1fr}.filters select{min-width:0;width:100%}.task{grid-template-columns:1fr}.actions{justify-content:flex-start}.form-row{grid-template-columns:1fr}}
</style><script src="/assets/crm-custom-fields.js" defer></script></head><body><div class="app"><aside><div class="brand">فانل <b>CRM</b></div><nav aria-label="ماژول‌های CRM"><a class="nav" href="/workspace/marketing-manager">میزکار مدیر</a><a class="nav" href="/workspace/crm-customers">پرونده‌های مشتریان</a><a class="nav active" aria-current="page" href="/workspace/crm-custom-fields">فیلدهای سفارشی</a><a class="nav" href="/workspace/crm-security-integrations">امنیت و اتصال</a></nav></aside><main class="main"><h1>فیلدهای سفارشی CRM</h1><p class="sub">اطلاعات مورد نیاز کسب‌وکار را برای پرونده‌ها و فرصت‌ها تعریف کنید.</p><div class="filters"><label class="field">فضای کاری<select id="workspace"></select></label><button id="refresh" class="secondary" type="button">به‌روزرسانی</button></div><p id="message" role="status" aria-live="polite"></p><div class="layout"><section class="card"><h2>فیلدهای تعریف‌شده</h2><p id="count" class="notice"></p><div id="fields" class="queue"></div><p class="notice">این فهرست حداکثر ۵۰۰ تعریف دریافت‌شده را نمایش می‌دهد. مدیریت فیلدها به مجوز مربوط در ریشهٔ فضای کاری نیاز دارد.</p></section><section class="card"><h2 id="editor-title">تعریف فیلد جدید</h2><form id="field-form" class="form"><label class="field">کاربرد<select id="entity"><option value="person">شخص</option><option value="organization">سازمان</option><option value="lead">سرنخ</option><option value="opportunity">فرصت فروش</option></select></label><label class="field">شناسهٔ فیلد<input id="key" required pattern="[a-z][a-z0-9_]{0,79}" maxlength="80" placeholder="customer_category" dir="ltr"></label><p class="notice">شناسه با حرف کوچک انگلیسی شروع می‌شود و فقط حروف کوچک، عدد و زیرخط دارد. پس از ثبت قابل تغییر نیست.</p><label class="field">نام نمایشی<input id="name" required maxlength="160"></label><label class="field">نوع داده<select id="type"><option value="text">متن</option><option value="number">عدد</option><option value="boolean">بله / خیر</option><option value="date">تاریخ</option><option value="choice">انتخاب از فهرست</option></select></label><label id="options-label" class="field" hidden>گزینه‌ها؛ هر گزینه در یک سطر<textarea id="options" rows="5"></textarea></label><label><input id="required" type="checkbox"> اجباری</label><label id="active-label" hidden><input id="active" type="checkbox" checked> فعال</label><button id="save" class="primary" type="submit">ذخیرهٔ فیلد</button><button id="cancel" class="secondary" type="button">فیلد جدید / انصراف</button></form><p class="notice">نوع داده، کاربرد و شناسهٔ فیلد پس از ثبت ثابت‌اند. اجباری‌کردن فیلد یا حذف گزینهٔ استفاده‌شده ممکن است با توجه به داده‌های موجود توسط سرور رد شود.</p></section></div></main></div></body></html>"""
_SCRIPT = r"""(()=>{
const $=id=>document.getElementById(id),ws=$("workspace"),fmt=new Intl.NumberFormat("fa-IR"),entities={person:"شخص",organization:"سازمان",lead:"سرنخ",opportunity:"فرصت فروش"},types={text:"متن",number:"عدد",boolean:"بله / خیر",date:"تاریخ",choice:"انتخاب از فهرست"};
let editing=null,busy=false,generation=0;
function el(tag,text,cls=""){const n=document.createElement(tag);n.textContent=String(text??"");if(cls)n.className=cls;return n}
function say(text){$("message").textContent=text}
async function api(path,options={}){const res=await fetch(path,{...options,credentials:"same-origin",headers:{Accept:"application/json","Content-Type":"application/json","X-Workspace-ID":ws.value}});let data={};try{data=await res.json()}catch(_){}if(!res.ok)throw Error(typeof data.detail==="string"?data.detail:"درخواست ناموفق بود؛ مجوز و مقادیر را بررسی کنید.");return data}
function syncType(){$("options-label").hidden=$("type").value!=="choice"}
function resetEditor(){editing=null;$("field-form").reset();for(const id of ["entity","key","type"])$(id).disabled=false;$("active-label").hidden=true;$("editor-title").textContent="تعریف فیلد جدید";syncType()}
function editField(field,selected=ws.value){if(busy||selected!==ws.value)return;editing={...field,workspace:ws.value};$("entity").value=field.entity_kind;$("key").value=field.field_key;$("name").value=field.display_name;$("type").value=field.value_type;$("options").value=field.options.join("\n");$("required").checked=field.is_required;$("active").checked=field.is_active;for(const id of ["entity","key","type"])$(id).disabled=true;$("active-label").hidden=false;$("editor-title").textContent="ویرایش فیلد: "+field.display_name;syncType()}
function payload(){const display_name=$("name").value.trim(),choice=$("type").value==="choice",options=choice?$("options").value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean):[];if(!display_name)throw Error("نام نمایشی را وارد کنید.");if(choice&&(!options.length||options.length>100||new Set(options).size!==options.length||options.some(x=>x.length>160)))throw Error("گزینه‌ها باید یکتا و حداکثر ۱۰۰ گزینه با طول ۱۶۰ نویسه باشند.");if(editing){const changes={};if(display_name!==editing.display_name)changes.display_name=display_name;if($("required").checked!==editing.is_required)changes.is_required=$("required").checked;if($("active").checked!==editing.is_active)changes.is_active=$("active").checked;if(choice&&JSON.stringify(options)!==JSON.stringify(editing.options))changes.options=options;return changes}const key=$("key").value.trim();if(!/^[a-z][a-z0-9_]{0,79}$/.test(key))throw Error("شناسهٔ معتبر برای فیلد وارد کنید.");return {entity_kind:$("entity").value,field_key:key,display_name,value_type:$("type").value,options,is_required:$("required").checked}}
function render(fields){const selected=ws.value;$("count").textContent="تعداد دریافت‌شده: "+fmt.format(fields.length);const box=$("fields");box.replaceChildren();if(!fields.length){box.append(el("p","هنوز فیلدی تعریف نشده است.","empty"));return}for(const field of fields){const row=el("article","","task"),info=el("div","");info.append(el("strong",field.display_name),el("p",(entities[field.entity_kind]||field.entity_kind)+" · "+(types[field.value_type]||field.value_type)+" · "+(field.is_required?"اجباری":"اختیاری")+" · "+(field.is_active?"فعال":"غیرفعال")),el("p",field.field_key));const edit=el("button","ویرایش","secondary");edit.type="button";edit.addEventListener("click",()=>editField(field,selected));row.append(info,edit);box.append(row)}}
async function load(){const version=++generation;$("fields").replaceChildren();$("count").textContent="";if(!ws.value)return;say("در حال دریافت تعاریف…");try{const data=await api("/api/v1/crm/custom-fields");if(version!==generation)return;render(data);say("تعاریف به‌روز شد.")}catch(e){if(version===generation)say(e.message)}}
async function save(event){event.preventDefault();if(busy||!ws.value)return;if(editing&&editing.workspace!==ws.value){resetEditor();return}let data;try{data=payload()}catch(e){say(e.message);return}if(!Object.keys(data).length){say("تغییری برای ذخیره وجود ندارد.");return}busy=true;ws.disabled=true;$("save").disabled=true;try{await api("/api/v1/crm/custom-fields"+(editing?"/"+encodeURIComponent(editing.id):""),{method:editing?"PATCH":"POST",body:JSON.stringify(data)});resetEditor();await load()}catch(e){say("ذخیره انجام نشد: "+e.message)}finally{busy=false;ws.disabled=false;$("save").disabled=false}}
async function init(){try{const spaces=await api("/api/v1/system/workspaces");ws.replaceChildren();const ph=el("option","فضای کاری را انتخاب کنید");ph.value="";ws.append(ph);for(const space of spaces){const option=el("option",space.name);option.value=space.id;ws.append(option)}if(spaces.length===1){ws.value=spaces[0].id;await load()}}catch(e){say(e.message)}}
ws.addEventListener("change",()=>{resetEditor();load()});$("refresh").addEventListener("click",load);$("type").addEventListener("change",syncType);$("cancel").addEventListener("click",()=>{if(!busy)resetEditor()});$("field-form").addEventListener("submit",save);
init();
})();"""

@router.get("/workspace/crm-custom-fields", response_class=HTMLResponse)
async def custom_fields_page() -> HTMLResponse:
    return HTMLResponse(_PAGE, headers=_HEADERS)

@router.get("/assets/crm-custom-fields.js")
async def custom_fields_script() -> Response:
    return Response(_SCRIPT, media_type="application/javascript", headers=_HEADERS)
